375	<script>
376	  const stage = document.getElementById('stage');
377	  const slides = [...document.querySelectorAll('.slide')];
378	  let cur = 0;
379	
380	  function fit() {
381	    const s = Math.min(window.innerWidth / 1600, window.innerHeight / 900);
382	    stage.style.transform = `translate(-50%, -50%) scale(${s})`;
383	  }
384	  function show(n) {
385	    cur = Math.max(0, Math.min(slides.length - 1, n));
386	    slides.forEach((el, i) => {
387	      el.classList.toggle('active', i === cur);
388	      el.querySelectorAll('.fill').forEach(f => f.style.width = i === cur ? f.dataset.w + '%' : '0');
389	    });
390	    document.getElementById('progress').style.width = ((cur + 1) / slides.length * 100) + '%';
391	    document.getElementById('counter').textContent = (cur + 1) + ' / ' + slides.length;
392	    history.replaceState(null, '', '#' + (cur + 1));
393	  }
394	  document.addEventListener('keydown', e => {
395	    if (['ArrowRight', 'PageDown', ' ', 'Enter'].includes(e.key)) { e.preventDefault(); show(cur + 1); }
396	    if (['ArrowLeft', 'PageUp', 'Backspace'].includes(e.key)) { e.preventDefault(); show(cur - 1); }
397	    if (e.key === 'Home') show(0);
398	    if (e.key === 'End') show(slides.length - 1);
399	    if (e.key === 'f') document.documentElement.requestFullscreen?.();
400	  });
401	  document.addEventListener('click', e => show(cur + (e.clientX < window.innerWidth / 3 ? -1 : 1)));
402	  const fillAll = () => document.querySelectorAll('.fill').forEach(f => f.style.width = f.dataset.w + '%');
403	  window.addEventListener('beforeprint', fillAll);
404	  if (location.search.includes('all')) {
405	    document.body.classList.add('all');
406	    fillAll();
407	  } else {
408	    window.addEventListener('resize', fit);
409	    fit();
410	    show((parseInt(location.hash.slice(1)) || 1) - 1);
411	  }
412	</script>
