.g2 { grid-template-columns: repeat(2, 1fr); }
a { color: inherit; text-decoration: none; }
.brand a { color: var(--muted); border-bottom: 1px solid var(--line); margin-left: 6px; }
.brand a:hover { color: var(--mint); border-color: var(--mint); }
a.card { display: block; transition: border-color .2s, transform .2s; }
a.card:hover { border-color: rgba(62,230,168,.6); transform: translateY(-4px); }
.visit { display: inline-block; margin-top: 26px; font: 600 20px var(--head); color: var(--mint); }
.split { display: grid; grid-template-columns: 1fr 560px; gap: 80px; flex: 1; align-items: center; margin-top: 30px; }
.accts { display: flex; flex-direction: column; gap: 16px; }
.acct { display: flex; justify-content: space-between; align-items: center; background: var(--panel); border: 1px solid var(--line);
  border-radius: 16px; padding: 22px 30px; font: 600 24px var(--head); }
.acct span { font: 400 19px var(--body); color: var(--dim); }
.acct.q { border-style: dashed; color: var(--coral); justify-content: center; }
.widget .live { display: inline-flex; align-items: center; gap: 10px; font: 600 15px var(--head); letter-spacing: .12em;
  text-transform: uppercase; color: var(--mint); }
.widget .live i { width: 9px; height: 9px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 12px var(--mint); }
.widget h3 { margin-top: 14px; }
.route { background: var(--panel); border: 1px solid var(--line); border-radius: 22px; padding: 40px 42px; }
.route .tag { display: inline-block; font: 600 16px var(--head); letter-spacing: .1em; padding: 8px 16px; border-radius: 99px;
  background: var(--coral-soft); color: var(--coral); margin-bottom: 22px; }
.route ul { list-style: none; margin-top: 22px; display: flex; flex-direction: column; gap: 14px; }
.route li { font-size: 22px; color: var(--muted); padding-left: 26px; position: relative; line-height: 1.4; }
.route li::before { content: ''; position: absolute; left: 0; top: 12px; width: 8px; height: 8px; border-radius: 50%; background: var(--coral); }
.rung.us { border-color: rgba(62,230,168,.45); background: linear-gradient(90deg, rgba(62,230,168,.08), var(--panel) 60%); }

