// Builds presentation/LeanInference.pptx (Google Slides compatible) and spec.json for preview QA.
const fs = require("fs");
const pptxgen = require("pptxgenjs");
const SKILL = "C:/Users/mgsuk/.claude/skills/synced/d29ec941-466a-4d43-af12-9ba3ab59bf3f_6abab35a-967c-4a33-98b4-8d2a6b27256b/pptx";
const { applyTheme } = require(SKILL + "/scripts/apply_theme.js");
const OUT = process.argv[2] || "LeanInference.pptx";

// Dark deck: dk1 holds the light text color so new text added in Slides is readable by default.
const THEME = {
  name: "LeanInference",
  headFontFace: "Space Grotesk",
  bodyFontFace: "Inter",
  colors: {
    dk1: "E8EDF3", lt1: "0A0E14", dk2: "8A97A8", lt2: "111823",
    accent1: "3EE6A8", accent2: "FF7A6B", accent3: "1F2A38", accent4: "5B6878",
    accent5: "0C121B", accent6: "3C4757", hlink: "3EE6A8", folHlink: "3EE6A8",
  },
};
const HEX = { text: "E8EDF3", bg: "0A0E14", muted: "8A97A8", panel: "111823", mint: "3EE6A8", coral: "FF7A6B", line: "1F2A38", dim: "5B6878", track: "0C121B" };

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.333 x 7.5
pres.title = "LeanInference";
pres.author = "LeanInference";
pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
const C = pres.SchemeColor;
const COL = { text: C.text1, bg: C.background1, muted: C.text2, panel: C.background2, mint: C.accent1, coral: C.accent2, line: C.accent3, dim: C.accent4, track: C.accent5 };
const R = pres.ShapeType;
const HEAD = THEME.headFontFace, BODY = THEME.bodyFontFace;

// ---------- preview spec recorder ----------
const spec = [];
let cur = null;
const hexOf = (c) => {
  if (!c) return null;
  const m = { [COL.text]: HEX.text, [COL.bg]: HEX.bg, [COL.muted]: HEX.muted, [COL.panel]: HEX.panel, [COL.mint]: HEX.mint, [COL.coral]: HEX.coral, [COL.line]: HEX.line, [COL.dim]: HEX.dim, [COL.track]: HEX.track };
  return m[c] || c;
};
function rec(o) { cur.items.push(o); }
function normRuns(t) { return typeof t === "string" ? [{ text: t, options: {} }] : t; }
function recText(runs, o, ph) {
  rec({
    kind: "text", x: o.x, y: o.y, w: o.w, h: o.h, ph: ph || null,
    size: o.fontSize, bold: !!o.bold, font: o.fontFace || BODY, color: hexOf(o.color), align: o.align || "left", valign: o.valign || "top",
    lineSpacingMultiple: o.lineSpacingMultiple || 1.2, charSpacing: o.charSpacing || 0,
    fill: o.fill ? hexOf(o.fill.color) : null, fillT: o.fill ? o.fill.transparency || 0 : 0, rectRadius: o.rectRadius || 0,
    runs: normRuns(runs).map((r) => ({ text: r.text, bold: r.options.bold, color: hexOf(r.options.color), size: r.options.fontSize, font: r.options.fontFace, breakLine: !!r.options.breakLine, bullet: !!r.options.bullet })),
  });
}

// ---------- layouts ----------
const LAYOUT_PH = {}; // name -> { phName -> options }
function brandObjects(name) {
  return [
    { text: { text: "■", options: { x: 1.0, y: 6.82, w: 0.22, h: 0.3, fontFace: BODY, fontSize: 11, color: COL.mint, margin: 0, valign: "middle" } } },
    { text: { text: name, options: { x: 1.22, y: 6.82, w: 3.5, h: 0.3, fontFace: HEAD, fontSize: 11, bold: true, color: COL.dim, margin: 0, valign: "middle" } } },
  ];
}
function layout(title, phs, extra = []) {
  LAYOUT_PH[title] = {};
  const objects = [...extra];
  for (const [name, opt] of Object.entries(phs)) {
    LAYOUT_PH[title][name] = opt;
    objects.push({ placeholder: { options: { name, type: opt.type, x: opt.x, y: opt.y, w: opt.w, h: opt.h, fontFace: opt.fontFace, fontSize: opt.fontSize, bold: opt.bold, color: opt.color, valign: "top", margin: 0, charSpacing: opt.charSpacing, lineSpacingMultiple: opt.lineSpacingMultiple }, text: "" } });
  }
  pres.defineSlideMaster({ title, background: { color: COL.bg }, objects });
}
const KICKER = { type: "body", x: 1.0, y: 0.72, w: 11.33, h: 0.32, fontFace: HEAD, fontSize: 12, bold: true, color: COL.mint, charSpacing: 3 };
const TITLE = { type: "title", x: 1.0, y: 1.1, w: 11.33, h: 1.3, fontFace: HEAD, fontSize: 36, bold: true, color: COL.text, lineSpacingMultiple: 0.95 };
const CASE_TITLE = { ...TITLE, w: 5.6, h: 1.45, fontSize: 30 };

layout("Title", {
  title: { type: "title", x: 1.0, y: 2.05, w: 11.33, h: 1.95, fontFace: HEAD, fontSize: 54, bold: true, color: COL.text, lineSpacingMultiple: 0.95 },
  body: { type: "body", x: 1.0, y: 4.3, w: 8.6, h: 1.7, fontFace: BODY, fontSize: 18, color: COL.muted, lineSpacingMultiple: 1.3 },
});
layout("Section divider", {
  kicker: { ...KICKER, y: 1.25 },
  title: { type: "title", x: 1.0, y: 1.65, w: 11.33, h: 1.85, fontFace: HEAD, fontSize: 54, bold: true, color: COL.text, lineSpacingMultiple: 0.95 },
});
for (const [brand, key] of [["LeanInference", "LI"], ["Moneo", "Moneo"], ["UniPirate", "Uni"]]) {
  layout(`Content ${key}`, { kicker: KICKER, title: TITLE }, brandObjects(brand));
  layout(`Case ${key}`, { kicker: KICKER, title: CASE_TITLE }, brandObjects(brand));
}

// ---------- slide helpers ----------
function newSlide(masterName, sectionTitle) {
  const s = pres.addSlide({ masterName, sectionTitle });
  cur = { layout: masterName, items: [] };
  spec.push(cur);
  const brand = masterName.endsWith("LI") ? "LeanInference" : masterName.endsWith("Moneo") ? "Moneo" : masterName.endsWith("Uni") ? "UniPirate" : null;
  if (brand) {
    rec({ kind: "text", x: 1.0, y: 6.82, w: 0.22, h: 0.3, size: 11, font: BODY, color: HEX.mint, align: "left", valign: "middle", lineSpacingMultiple: 1.2, runs: [{ text: "■" }] });
    rec({ kind: "text", x: 1.22, y: 6.82, w: 3.5, h: 0.3, size: 11, bold: true, font: HEAD, color: HEX.dim, align: "left", valign: "middle", lineSpacingMultiple: 1.2, runs: [{ text: brand }] });
  }
  return s;
}
function ph(s, name, runs) {
  s.addText(runs, { placeholder: name });
  const o = LAYOUT_PH[cur.layout][name];
  recText(runs, o, name);
}
function text(s, runs, o) {
  const opt = { isTextBox: true, margin: 0, valign: "top", fontFace: BODY, color: COL.text, lineSpacingMultiple: 1.2, ...o };
  s.addText(runs, opt);
  recText(runs, opt);
}
function shape(s, type, o) {
  s.addShape(type, o);
  rec({ kind: "shape", type: type === R.ellipse ? "ellipse" : type === R.roundRect ? "round" : "rect", x: o.x, y: o.y, w: o.w, h: o.h, rectRadius: o.rectRadius || 0,
    fill: o.fill ? hexOf(o.fill.color) : null, fillT: o.fill ? o.fill.transparency || 0 : 0, line: o.line ? hexOf(o.line.color) : null, lineT: o.line ? o.line.transparency || 0 : 0, dash: o.line ? o.line.dashType : null });
}
function card(s, x, y, w, h, hl = false, name = "Card") {
  shape(s, R.roundRect, { x, y, w, h, rectRadius: 0.2, fill: { color: COL.panel }, line: { color: hl ? COL.mint : COL.line, width: hl ? 1.25 : 0.75, transparency: hl ? 40 : 0 }, objectName: name });
}
function pill(s, label, x, y, w, color, name = "Tag") {
  text(s, label, { x, y, w, h: 0.38, shape: R.roundRect, rectRadius: 0.19, fill: { color, transparency: 86 }, color, fontFace: HEAD, fontSize: 10, bold: true, align: "center", valign: "middle", charSpacing: 1, objectName: name });
}
const B = (t) => ({ text: t, options: { bold: true, color: COL.text } });
const M = (t, extra = {}) => ({ text: t, options: { color: COL.muted, ...extra } });
const MINT = (t, extra = {}) => ({ text: t, options: { color: COL.mint, ...extra } });
const CORAL = (t, extra = {}) => ({ text: t, options: { color: COL.coral, ...extra } });
const W = (t, extra = {}) => ({ text: t, options: { ...extra } });

function stepCard(s, x, y, w, h, num, title, body, hl, titleSize = 20) {
  card(s, x, y, w, h, hl, `Card ${num}`);
  text(s, num, { x: x + 0.35, y: y + 0.35, w: w - 0.7, h: 0.3, fontFace: HEAD, fontSize: 12, bold: true, color: COL.mint, charSpacing: 2 });
  text(s, title, { x: x + 0.35, y: y + 0.8, w: w - 0.7, h: 0.45, fontFace: HEAD, fontSize: titleSize, bold: true });
  text(s, body, { x: x + 0.35, y: y + 1.35, w: w - 0.7, h: h - 1.6, fontSize: 14, color: COL.muted, lineSpacingMultiple: 1.35 });
}
function painRows(s, x, w, rows, y0, step, h) {
  rows.forEach(([b, rest], i) => {
    const y = y0 + i * step;
    shape(s, R.ellipse, { x, y: y + 0.1, w: 0.11, h: 0.11, fill: { color: COL.coral }, line: { color: COL.coral, width: 0 }, objectName: `Dot ${i + 1}` });
    text(s, [B(b), M(" " + rest)], { x: x + 0.3, y, w: w - 0.3, h, fontSize: 15, lineSpacingMultiple: 1.35 });
  });
}
function facts(s, items, y0, step) {
  items.forEach((runs, i) => {
    const y = y0 + i * step;
    text(s, "✓", { x: 1.0, y, w: 0.3, h: 0.3, fontSize: 15, bold: true, color: COL.mint });
    text(s, runs, { x: 1.35, y, w: 5.25, h: step - 0.04, fontSize: 14, color: COL.muted, lineSpacingMultiple: 1.3 });
  });
}
// Cost panel on the right of case slides. rows: [label, value, pct, kind('old'|'new'), valueColor]
function costPanel(s, label, rows, big, bigText, opts = {}) {
  const x = 7.0, y = 1.15, w = 5.33, h = 5.4, ix = x + 0.45, iw = w - 0.9;
