"""Approximate preview of spec.json (what build.js placed) with the real fonts; flags overflow."""
import json, sys
from PIL import Image, ImageDraw, ImageFont
from fontTools.ttLib import TTFont

S = 120  # px per inch
FILES = {"Inter": "Inter.ttf", "Space Grotesk": "SpaceGrotesk.ttf"}
CMAP = {k: set(TTFont(v).getBestCmap().keys()) for k, v in FILES.items()}
SYM = "C:/Windows/Fonts/seguisym.ttf"
_cache = {}

def font(face, bold, px):
    key = (face, bold, round(px))
    if key not in _cache:
        f = ImageFont.truetype(FILES.get(face, "Inter.ttf"), round(px))
        try:
            f.set_variation_by_name(b"Bold" if bold else b"Regular")
        except Exception:
            pass
        _cache[key] = f
    return _cache[key]

def sym(px):
    return ImageFont.truetype(SYM, round(px))

def hexrgb(h): return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))
def blend(c, bg, t):  # t = transparency 0..100
    a = 1 - t / 100
    return tuple(round(c[i] * a + bg[i] * (1 - a)) for i in range(3))

def seg_width(text, f, face, px, cs):
    w = 0
    for ch in text:
        ff = f if ord(ch) in CMAP.get(face, CMAP["Inter"]) else sym(px)
        w += ff.getlength(ch) + cs
    return w

def draw_seg(d, x, y, text, f, face, px, cs, col):
    for ch in text:
        ff = f if ord(ch) in CMAP.get(face, CMAP["Inter"]) else sym(px)
        d.text((x, y), ch, font=ff, fill=col)
        x += ff.getlength(ch) + cs
    return x

def layout_text(it):
    """Wrap runs into lines of (segments). Returns lines, line_height."""
    size_px = it["size"] * S / 72
    lh = size_px * 1.2 * it["lineSpacingMultiple"]
    maxw = it["w"] * S
    paras, curp = [], []
    for r in it["runs"]:
        curp.append(r)
        if r.get("breakLine"):
            paras.append(curp); curp = []
    if curp: paras.append(curp)
    lines = []
    for p in paras:
        bullet = any(r.get("bullet") for r in p)
        indent = 0.19 * S if bullet else 0
        words = []
        for r in p:
            face = r.get("font") or it["font"]
            bold = r["bold"] if r.get("bold") is not None else it["bold"]
            px = (r.get("size") or it["size"]) * S / 72
            col = r.get("color") or it["color"] or "E8EDF3"
            toks = r["text"].replace("\n", " ").split(" ")
            for i, t in enumerate(toks):
                words.append((t, face, bold, px, col, i < len(toks) - 1))
        line, lw, first = [], indent, True
        cs = it.get("charSpacing", 0) * S / 72
        for (t, face, bold, px, col, sp) in words:
            f = font(face, bold, px)
            w = seg_width(t, f, face, px, cs)
            spw = f.getlength(" ") if sp else 0
            if line and lw + w > maxw + 0.5:
                lines.append((line, bullet and first)); first = False
                line, lw = [], indent
            line.append((t + (" " if sp else ""), face, bold, px, col, cs))
            lw += w + spw
        lines.append((line, bullet and first))
    return lines, lh

def render(slides, out_prefix):
    problems = []
    for n, sl in enumerate(slides, 1):
        bg = hexrgb("0A0E14")
        img = Image.new("RGB", (1600, 900), bg)
        d = ImageDraw.Draw(img)
        for it in sl["items"]:
            x, y, w, h = (it[k] * S for k in ("x", "y", "w", "h"))
            fillc = it.get("fill")
            if it["kind"] == "shape" or fillc:
                box = [x, y, x + w, y + h]
                fc = blend(hexrgb(fillc), bg, it.get("fillT", 0)) if fillc else None
                lc = blend(hexrgb(it["line"]), bg, it.get("lineT", 0)) if it.get("line") else None
                if it.get("type") == "ellipse":
                    d.ellipse(box, fill=fc, outline=lc)
                elif it.get("type") == "round" or it.get("rectRadius"):
                    d.rounded_rectangle(box, radius=min(it.get("rectRadius", 0) * S, h / 2, w / 2), fill=fc, outline=lc, width=2 if lc else 0)
                else:
                    d.rectangle(box, fill=fc, outline=lc)
                if it.get("label"):
                    d.text((x + 10, y + 10), it["label"], fill=(90, 100, 110), font=font("Inter", False, 16))
            if it["kind"] != "text":
                continue
            lines, lh = layout_text(it)
            total = len(lines) * lh
            if total > h + 2:
                problems.append(f"slide {n}: text overflows box by {(total - h) / S:.2f}in: {''.join(r['text'] for r in it['runs'])[:60]!r}")
            if x + w > 1600 - 0.4 * S + 1 and it.get("ph") is None and w > 1:
                problems.append(f"slide {n}: box past right margin")
            ty = y if it["valign"] == "top" else (y + h - total if it["valign"] == "bottom" else y + (h - total) / 2)
            for line, bul in lines:
                lw = sum(seg_width(t, font(fc_, b, px), fc_, px, cs) for t, fc_, b, px, c, cs in line)
                lx = x + (0.19 * S if any(True for _ in [0]) and line and False else 0)
                if it["align"] == "center": lx = x + (w - lw) / 2
                elif it["align"] == "right": lx = x + w - lw
                if bul:
                    d.ellipse([x + 4, ty + lh / 2 - 4, x + 10, ty + lh / 2 + 2], fill=hexrgb(line[0][4]))
                if any(r.get("bullet") for r in it["runs"]): lx = x + 0.19 * S
                base = ty + (lh - line[0][3] * 1.2) / 2 if line else ty
                for t, fc_, b, px, c, cs in line:
                    lx = draw_seg(d, lx, base, t, font(fc_, b, px), fc_, px, cs, hexrgb(c))
                ty += lh
        img.save(f"{out_prefix}-{n:02d}.png")
    return problems

if __name__ == "__main__":
    probs = render(json.load(open("spec.json", encoding="utf-8")), sys.argv[1] if len(sys.argv) > 1 else "prev")
    print("\n".join(probs) or "no overflow detected")
